using System.Globalization;
using Shouldly;

namespace Commerce.IntegrationTests.Infrastructure;

/// <summary>Verifies a prepared disposable copy changes only the selected generated bytes.</summary>
internal static class GeneratedStartupControls
{
    /// <summary>Requires every generated byte, filename and relative path to match the pristine tree.</summary>
    /// <param name="pristine">The untouched same-revision generated tree.</param>
    /// <param name="current">The observed generated tree.</param>
    /// <param name="because">The assertion context.</param>
    internal static void AssertUnchanged(GeneratedHostTree pristine, GeneratedHostTree current, string because)
    {
        ArgumentNullException.ThrowIfNull(pristine);
        ArgumentNullException.ThrowIfNull(current);
        current.FileCount.ShouldBe(pristine.FileCount, because + " must keep the exact generated file set");
        AssertIdenticalExcept(pristine, current, [], because);
    }

    /// <summary>Requires exactly the registry source to be absent and everything else byte-identical.</summary>
    /// <param name="pristine">The untouched same-revision generated tree.</param>
    /// <param name="current">The prepared disposable copy's generated tree.</param>
    /// <param name="host">The selected host.</param>
    internal static void AssertRegistryRemoved(GeneratedHostTree pristine, GeneratedHostTree current, CommerceStaticHost host)
    {
        ArgumentNullException.ThrowIfNull(pristine);
        ArgumentNullException.ThrowIfNull(current);
        ArgumentNullException.ThrowIfNull(host);
        var because = host.Name + " registry-only negative control";
        current.Contains(pristine.RegistryPath).ShouldBeFalse(because + " must remove " + pristine.RegistryPath);
        current.FileCount.ShouldBe(pristine.FileCount - 1, because + " must not change any other file");
        AssertIdenticalExcept(pristine, current, [pristine.RegistryPath], because);
    }

    /// <summary>Requires exactly the handler adapter and its single registry root attribute to be absent.</summary>
    /// <param name="pristine">The untouched same-revision generated tree.</param>
    /// <param name="current">The prepared disposable copy's generated tree.</param>
    /// <param name="host">The selected host.</param>
    /// <returns>The removed adapter type identity.</returns>
    internal static AdapterLoss AssertAdapterRemoved(GeneratedHostTree pristine, GeneratedHostTree current, CommerceStaticHost host)
    {
        ArgumentNullException.ThrowIfNull(pristine);
        ArgumentNullException.ThrowIfNull(current);
        ArgumentNullException.ThrowIfNull(host);
        var because = host.Name + " adapter-only negative control";
        var adapterPath = FindAdapter(pristine, host);
        var loss = new AdapterLoss(GeneratedTypeName(pristine, adapterPath, qualified: true), GeneratedTypeName(pristine, adapterPath, qualified: false));
        current.Contains(adapterPath).ShouldBeFalse(because + " must remove " + adapterPath);
        current.FileCount.ShouldBe(pristine.FileCount - 1, because + " must remove exactly one adapter file");
        current.Files.Count(path => !string.Equals(path, current.RegistryPath, StringComparison.Ordinal)
            && current.Text(path).Contains(host.HandlerTypeName, StringComparison.Ordinal)).ShouldBe(0, because + " must leave no adapter invoking " + host.HandlerTypeName);
        AssertIdenticalExcept(pristine, current, [adapterPath, pristine.RegistryPath], because);
        AssertRegistryRootRemoved(pristine, current, loss, because);
        return loss;
    }

    private static void AssertIdenticalExcept(
        GeneratedHostTree pristine,
        GeneratedHostTree current,
        IReadOnlyList<string> except,
        string because)
    {
        foreach (var pair in pristine.Hashes)
        {
            if (except.Contains(pair.Key, StringComparer.Ordinal))
            {
                continue;
            }

            current.Contains(pair.Key).ShouldBeTrue(because + " is missing " + pair.Key);
            current.Hash(pair.Key).ShouldBe(pair.Value, because + " changed " + pair.Key);
        }
    }

    private static string FindAdapter(GeneratedHostTree pristine, CommerceStaticHost host)
    {
        var adapters = pristine.Files
            .Where(path => !string.Equals(path, pristine.RegistryPath, StringComparison.Ordinal)
                && pristine.Text(path).Contains(host.HandlerTypeName, StringComparison.Ordinal))
            .ToArray();
        adapters.Length.ShouldBe(1, host.Name + " must have exactly one generated adapter invoking " + host.HandlerTypeName);
        return adapters[0];
    }

    private static void AssertRegistryRootRemoved(
        GeneratedHostTree pristine,
        GeneratedHostTree current,
        AdapterLoss loss,
        string because)
    {
        var pristineLines = pristine.RegistryText.Split('\n');
        var currentLines = current.RegistryText.Split('\n');
        var matches = Enumerable.Range(0, pristineLines.Length)
            .Where(index => IsAdapterRoot(pristineLines[index], loss))
            .ToArray();
        matches.Length.ShouldBe(1, because + " must have exactly one DynamicDependency root for " + loss.FullName);
        var removed = matches[0];
        CountOccurrences(pristineLines[removed], "typeof(").ShouldBe(1, because + " root line must carry one type reference");
        currentLines.Length.ShouldBe(pristineLines.Length - 1, because + " must remove exactly the adapter root line");
        for (var index = 0; index < removed; index++)
        {
            currentLines[index].ShouldBe(
                pristineLines[index],
                because + " changed registry line " + index.ToString(CultureInfo.InvariantCulture));
        }

        for (var index = removed; index < currentLines.Length; index++)
        {
            currentLines[index].ShouldBe(
                pristineLines[index + 1],
                because + " changed registry line " + index.ToString(CultureInfo.InvariantCulture));
        }
    }

    private static bool IsAdapterRoot(string line, AdapterLoss loss) =>
        line.Contains("DynamicDependency", StringComparison.Ordinal)
        && (line.Contains(loss.FullName, StringComparison.Ordinal)
            || line.Contains("typeof(" + loss.Name + ")", StringComparison.Ordinal));

    private static int CountOccurrences(string value, string token)
    {
        var count = 0;
        var index = value.IndexOf(token, StringComparison.Ordinal);
        while (index >= 0)
        {
            count++;
            index = value.IndexOf(token, index + token.Length, StringComparison.Ordinal);
        }

        return count;
    }

    private static string GeneratedTypeName(GeneratedHostTree tree, string relativePath, bool qualified)
    {
        var text = tree.Text(relativePath);
        var name = ReadClassName(text, relativePath);
        if (!qualified)
        {
            return name;
        }

        var space = ReadNamespace(text);
        return string.IsNullOrEmpty(space) ? name : space + "." + name;
    }

    private static string ReadNamespace(string text)
    {
        foreach (var line in text.Split('\n'))
        {
            var trimmed = line.Trim();
            if (!trimmed.StartsWith("namespace ", StringComparison.Ordinal))
            {
                continue;
            }

            return trimmed["namespace ".Length..].TrimEnd(';', '{', ' ', '\r');
        }

        return string.Empty;
    }

    private static string ReadClassName(string text, string relativePath)
    {
        foreach (var line in text.Split('\n'))
        {
            var index = line.IndexOf("class ", StringComparison.Ordinal);
            if (index < 0)
            {
                continue;
            }

            var start = index + "class ".Length;
            var end = start;
            while (end < line.Length && (char.IsLetterOrDigit(line[end]) || line[end] == '_'))
            {
                end++;
            }

            var name = line[start..end];
            name.ShouldNotBeNullOrWhiteSpace(relativePath + " must declare the generated handler class");
            return name;
        }

        throw new InvalidOperationException("No generated class declaration in " + relativePath + ".");
    }
}
